package co.edu.udea.bookingnow.application.service;

import co.edu.udea.bookingnow.application.port.in.reserva.*;
import co.edu.udea.bookingnow.application.port.out.*;
import co.edu.udea.bookingnow.domain.exception.*;
import co.edu.udea.bookingnow.domain.model.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;

@Service public class ReservaService implements RegistrarReservaUseCase,ConsultarDisponibilidadUseCase {
 private final ServicioRepositoryPort servicios; private final ClienteRepositoryPort clientes; private final AsignacionServicioRepositoryPort asignaciones; private final HorarioAtencionRepositoryPort horarios; private final EmpleadoRepositoryPort empleados; private final RecursoRepositoryPort recursos; private final ReservaRepositoryPort reservas;
 public ReservaService(ServicioRepositoryPort s,ClienteRepositoryPort c,AsignacionServicioRepositoryPort a,HorarioAtencionRepositoryPort h,EmpleadoRepositoryPort e,RecursoRepositoryPort r,ReservaRepositoryPort b){servicios=s;clientes=c;asignaciones=a;horarios=h;empleados=e;recursos=r;reservas=b;}
 private Servicio datos(Long id){return servicios.obtenerPorId(id).orElseThrow(()->new NoEncontradoException("Servicio no encontrado"));}
 private AsignacionServicio asignacion(Long id){return asignaciones.obtener(id).orElse(new AsignacionServicio(id,false,false,List.of(),List.of()));}
 private HorarioAtencion horario(Long negocio,LocalDate fecha){return horarios.listarPorNegocio(negocio).stream().filter(h->h.dia()==fecha.getDayOfWeek()).findFirst().orElseThrow(()->new ConflictoException("El negocio no atiende ese día"));}
 private boolean solapa(LocalTime inicio,int duracion,ReservaEnAgenda existente){LocalTime fin=inicio.plusMinutes(duracion);LocalTime finExistente=existente.hora().plusMinutes(existente.duracionMinutos());return inicio.isBefore(finExistente)&&fin.isAfter(existente.hora());}
 private List<ReservaEnAgenda> agenda(LocalDate fecha){return reservas.listarPorFecha(fecha).stream().filter(r->!r.estado().equals("CANCELADA")).toList();}
 private boolean empleadoLibre(Long id,LocalTime hora,int duracion,List<ReservaEnAgenda> agenda){return agenda.stream().filter(r->Objects.equals(r.idEmpleado(),id)).noneMatch(r->solapa(hora,duracion,r));}
 private boolean recursoLibre(Long id,int capacidad,LocalTime hora,int duracion,List<ReservaEnAgenda> agenda){return agenda.stream().filter(r->Objects.equals(r.idRecurso(),id)&&solapa(hora,duracion,r)).count()<capacidad;}
 public List<OpcionDisponibilidad> consultar(Long idServicio,LocalDate fecha){if(fecha==null)throw new IllegalArgumentException("La fecha es obligatoria");Servicio servicio=datos(idServicio);AsignacionServicio asignacion=asignacion(idServicio);HorarioAtencion h=horario(servicio.idNegocio(),fecha);List<ReservaEnAgenda> agenda=agenda(fecha);List<Empleado> emp=empleados.listarPorNegocio(servicio.idNegocio()).stream().filter(e->asignacion.idEmpleados().contains(e.idEmpleado())).toList();List<Recurso> rec=recursos.listarPorNegocio(servicio.idNegocio()).stream().filter(r->asignacion.idRecursos().contains(r.idRecurso())&&r.estado().equals("DISPONIBLE")).toList();List<OpcionDisponibilidad> slots=new ArrayList<>();for(LocalTime start=h.horaApertura();!start.plusMinutes(servicio.duracionMinutos()).isAfter(h.horaCierre());start=start.plusMinutes(servicio.duracionMinutos())){final LocalTime slot=start;List<Long> eids=emp.stream().filter(e->empleadoLibre(e.idEmpleado(),slot,servicio.duracionMinutos(),agenda)).map(Empleado::idEmpleado).toList();List<Long> rids=rec.stream().filter(r->recursoLibre(r.idRecurso(),r.cantidad(),slot,servicio.duracionMinutos(),agenda)).map(Recurso::idRecurso).toList();boolean ok=(!asignacion.requiereEmpleados()||!eids.isEmpty())&&(!asignacion.requiereRecursos()||!rids.isEmpty());if(ok)slots.add(new OpcionDisponibilidad(slot,eids,rids));}return List.copyOf(slots);}
 @Transactional public Reserva registrar(Long idCliente,RegistrarReservaCommand c){if(c==null)throw new IllegalArgumentException("Los datos de la reserva son obligatorios");if(c.idServicio()==null||c.fecha()==null||c.hora()==null)throw new IllegalArgumentException("Servicio, fecha y hora son obligatorios");clientes.obtenerPorId(idCliente).orElseThrow(()->new NoEncontradoException("Cliente no encontrado"));Servicio servicio=datos(c.idServicio());AsignacionServicio a=asignacion(c.idServicio());var h=horario(servicio.idNegocio(),c.fecha());LocalTime fin=c.hora().plusMinutes(servicio.duracionMinutos());if(c.hora().isBefore(h.horaApertura())||fin.isAfter(h.horaCierre()))throw new ConflictoException("La hora seleccionada está fuera del horario del negocio");if(a.requiereEmpleados()&&c.idEmpleado()==null)throw new ValidacionException(Map.of("idEmpleado","Selecciona un empleado porque el servicio lo requiere"));if(a.requiereRecursos()&&c.idRecurso()==null)throw new ValidacionException(Map.of("idRecurso","Selecciona un recurso porque el servicio lo requiere"));if(c.idEmpleado()!=null&&!a.idEmpleados().contains(c.idEmpleado()))throw new AccesoDenegadoException("El empleado no está asignado a este servicio");if(c.idRecurso()!=null&&!a.idRecursos().contains(c.idRecurso()))throw new AccesoDenegadoException("El recurso no está asignado a este servicio");var recurso=recursos.listarPorNegocio(servicio.idNegocio()).stream().filter(r->Objects.equals(r.idRecurso(),c.idRecurso())).findFirst();if(c.idRecurso()!=null&&(recurso.isEmpty()||!recurso.get().estado().equals("DISPONIBLE")))throw new ConflictoException("El recurso no está disponible");reservas.bloquearRecursos(c.idServicio(),c.idEmpleado(),c.idRecurso());List<ReservaEnAgenda> agenda=agenda(c.fecha());if(c.idEmpleado()!=null&&!empleadoLibre(c.idEmpleado(),c.hora(),servicio.duracionMinutos(),agenda))throw new ConflictoException("El empleado ya tiene una reserva en ese horario");if(c.idRecurso()!=null&&!recursoLibre(c.idRecurso(),recurso.orElseThrow().cantidad(),c.hora(),servicio.duracionMinutos(),agenda))throw new ConflictoException("El recurso ya no está disponible en ese horario");return reservas.guardar(new Reserva(null,idCliente,c.idServicio(),c.idEmpleado(),c.idRecurso(),c.fecha(),c.hora(),"CONFIRMADA",Instant.now()));}
}
